import{_ as o,C as n,o as e,c as m,a3 as t,j as i,E as s,a as r}from"./chunks/framework.C6R8kWFE.js";const T=JSON.parse(`{"title":"8-dars (Mentor). Kompyuter tarmoqlari asoslari: OSI 7 qatlamli modeli va TCP/IP steki","description":"","frontmatter":{"title":"8-dars (Mentor). Kompyuter tarmoqlari asoslari: OSI 7 qatlamli modeli va TCP/IP steki","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"10-sinf (DevOps)","link":"/mentor/10-sinf-devops/"},"week":{"n":3,"link":"/mentor/10-sinf-devops/hafta-03/"},"g":8,"title":"Kompyuter tarmoqlari asoslari: OSI 7 qatlamli modeli va TCP/IP steki","lead":"Internet qanday ishlaydi: LAN va WAN tarmoqlari, OSI 7 qatlamli etalon modeli, amaliy TCP/IP steki va ma'lumotlar sayohati (enkapsulyatsiya).","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-2-test.html","student_link":"/10-sinf-devops/hafta-03/dars-2","tabs":[{"g":7,"link":"/mentor/10-sinf-devops/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/10-sinf-devops/hafta-03/dars-2","current":true},{"g":9,"link":"/mentor/10-sinf-devops/hafta-03/dars-3","current":false}],"prev":{"g":7,"title":"Git branchlar va masofaviy repozitoriylar (GitHub, Push, Pull, Merge)","link":"/mentor/10-sinf-devops/hafta-03/dars-1"},"next":{"g":9,"title":"IP manzillash, Subnetting va tarmoq diagnostikasi vositalari","link":"/mentor/10-sinf-devops/hafta-03/dars-3"}}},"headers":[],"relativePath":"mentor/10-sinf-devops/hafta-03/dars-2.md","filePath":"mentor/10-sinf-devops/hafta-03/dars-2.md"}`),h={name:"mentor/10-sinf-devops/hafta-03/dars-2.md"},d={class:"blk"},p={id:"_1-dars-konspekti-mentor-uchun",tabindex:"-1"},u={class:"blk"},q={id:"_2-amaliy-topshiriqlar-va-yechimlari-mentor-uchun",tabindex:"-1"},y={class:"blk"},g={id:"_3-tezkor-nazorat-savollari-dars-yakuni",tabindex:"-1"};function k(c,a,v,b,P,f){const l=n("Icon");return e(),m("div",null,[a[9]||(a[9]=t("<p><strong>Darsning maqsadi:</strong> O&#39;quvchilarga DevOps sohasining muhim ustuni bo&#39;lgan kompyuter tarmoqlari asoslari, tarmoq turlari (LAN, WAN), tarmoq topologiyalari (Star, Mesh), ISO/OSI 7 qatlamli modeli va uning har bir bosqichi vazifasi, amaliy TCP/IP 4 qatlamli steki hamda ma&#39;lumotlar enkapsulyatsiyasi (Data -&gt; Segment -&gt; Packet -&gt; Frame -&gt; Bits) tamoyillarini chuqur va tizimli o&#39;rgatish.</p><p><strong>Vaqt taqsimoti:</strong></p><ul><li>O&#39;tgan mavzuni takrorlash (Git branchlar va GitHub): 10 daqiqa</li><li>Yangi mavzu: Tarmoq turlari, topologiyalar va nima uchun qatlamli model kerak: 20 daqiqa</li><li>Yangi mavzu: OSI 7 qatlamli modeli va TCP/IP steki taqqosi, enkapsulyatsiya: 25 daqiqa</li><li>Amaliy mashg&#39;ulot (Tarmoq interfeyslarini tahlil qilish: <code>ip a</code>, <code>ip route</code> va qatlamlarni solishtirish): 20 daqiqa</li><li>Dars xulosasi va tezkor nazorat: 5 daqiqa</li></ul><hr>",4)),i("div",d,[i("h2",p,[s(l,{name:"file-text"}),a[0]||(a[0]=r(" 1. Dars konspekti (Mentor uchun) ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-konspekti-mentor-uchun","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars konspekti (Mentor uchun)"'},"​",-1))]),a[2]||(a[2]=t('<h3 id="_1-1-devops-dunyosida-tarmoqlarning-o-rni" tabindex="-1">1.1. DevOps dunyosida tarmoqlarning o&#39;rni <a class="header-anchor" href="#_1-1-devops-dunyosida-tarmoqlarning-o-rni" aria-label="Permalink to &quot;1.1. DevOps dunyosida tarmoqlarning o&#39;rni&quot;">​</a></h3><p>DevOps muhandisi har kuni serverlar, konteynerlar (Docker) va mikroxizmatlar (Kubernetes) o&#39;rtasidagi aloqani sozlaydi. Agar tarmoq qanday ishlashini bilmasa, «serverga ulanib bo&#39;lmayapti» yoki «port yopiq» kabi oddiy muammolarni ham yecha olmaydi.</p><ul><li><strong>LAN (Local Area Network)</strong>: Cheklangan hududdagi (ofis, uy, maktab) kompyuterlarni bog&#39;lovchi mahalliy tarmoq.</li><li><strong>WAN (Wide Area Network)</strong>: Shaharlar, davlatlar va qit&#39;alarni birlashtiruvchi global tarmoq (eng yirik WAN — bu Internet).</li><li><strong>Asosiy tarmoq qurilmalari</strong>: <ul><li><strong>Switch (Kommutator)</strong>: Mahalliy tarmoq (LAN) ichida kompyuterlarni MAC-manzil bo&#39;yicha bog&#39;laydi (2-qatlam).</li><li><strong>Router (Marshrutizator)</strong>: Turli tarmoqlarni o&#39;zaro IP-manzil bo&#39;yicha bog&#39;laydi va ma&#39;lumot yo&#39;nalishini belgilaydi (3-qatlam).</li></ul></li></ul><h3 id="_1-2-osi-7-qatlamli-modeli-open-systems-interconnection" tabindex="-1">1.2. OSI 7 qatlamli modeli (Open Systems Interconnection) <a class="header-anchor" href="#_1-2-osi-7-qatlamli-modeli-open-systems-interconnection" aria-label="Permalink to &quot;1.2. OSI 7 qatlamli modeli (Open Systems Interconnection)&quot;">​</a></h3><p>ISO tashkiloti tomonidan yaratilgan konseptual etalon model. U tarmoq orqali axborot uzatish jarayonini 7 ta mantiqiy bosqichga ajratadi:</p><ol><li><strong>7. Application (Amaliy qatlam)</strong>: Foydalanuvchi dasturlari bilan to&#39;g&#39;ridan-to&#39;g&#39;ri ishlaydi (HTTP, HTTPS, SSH, DNS, FTP).</li><li><strong>6. Presentation (Taqdimot qatlami)</strong>: Ma&#39;lumotlarni kodlash, siqish va shifrlash (TLS/SSL, ASCII, JSON, JPEG).</li><li><strong>5. Session (Sessiya qatlami)</strong>: Ikkita tizim o&#39;rtasida aloqa seansini ochish, ushlab turish va yopish.</li><li><strong>4. Transport (Transport qatlami)</strong>: Ma&#39;lumotlarni yaxlit yetkazib berish, portlar va oqimni boshqarish (TCP, UDP). Ma&#39;lumot birligi: <strong>Segment</strong>.</li><li><strong>3. Network (Tarmoq qatlami)</strong>: Global marshrutlash va mantiqiy manzillash (IP, ICMP, ARP). Ma&#39;lumot birligi: <strong>Paket (Packet)</strong>.</li><li><strong>2. Data Link (Kanal qatlami)</strong>: Bitta mahalliy tarmoqdagi qurilmalararo jismoniy uzatish (Ethernet, Wi-Fi, MAC manzil). Ma&#39;lumot birligi: <strong>Freym (Frame)</strong>.</li><li><strong>1. Physical (Fizik qatlam)</strong>: Elektr, optik yoki radio signallari (bitlar: 0 va 1 lar, kabellar, razyomlar).</li></ol><h3 id="_1-3-tcp-ip-steki-amaliyotdagi-internet-modeli" tabindex="-1">1.3. TCP/IP steki: Amaliyotdagi Internet modeli <a class="header-anchor" href="#_1-3-tcp-ip-steki-amaliyotdagi-internet-modeli" aria-label="Permalink to &quot;1.3. TCP/IP steki: Amaliyotdagi Internet modeli&quot;">​</a></h3><p>OSI — bu nazariy etalon bo&#39;lsa, real Internet <strong>TCP/IP</strong> modeliga tayanadi. U 4 ta amaliy qatlamdan iborat:</p><ol><li><strong>Application (Amaliy)</strong>: OSI ning 7, 6, 5 qatlamlarini birlashtiradi (HTTP, SSH, DNS).</li><li><strong>Transport (Transport)</strong>: TCP va UDP protokollari (OSI 4-qatlami).</li><li><strong>Internet (Tarmoq)</strong>: IP (IPv4, IPv6) va ICMP (OSI 3-qatlami).</li><li><strong>Network Access (Tarmoqqa kirish)</strong>: OSI ning 1 va 2 qatlamlarini (Ethernet, Wi-Fi) birlashtiradi.</li></ol><h3 id="_1-4-enkapsulyatsiya-va-dekapsulyatsiya-paket-sayohati" tabindex="-1">1.4. Enkapsulyatsiya va Dekapsulyatsiya (Paket sayohati) <a class="header-anchor" href="#_1-4-enkapsulyatsiya-va-dekapsulyatsiya-paket-sayohati" aria-label="Permalink to &quot;1.4. Enkapsulyatsiya va Dekapsulyatsiya (Paket sayohati)&quot;">​</a></h3><ul><li><strong>Enkapsulyatsiya (Jo&#39;natishda)</strong>: Yuqori qatlamdan tushgan ma&#39;lumotga har bir quyi qatlam o&#39;zining xizmat sarlavhasini (Header) qo&#39;shadi: <ul><li>Application: <code>Data</code> (HTML yoki matn).</li><li>Transport: <code>TCP Header + Data</code> = <strong>Segment</strong> (port raqamlari qo&#39;shiladi).</li><li>Network: <code>IP Header + Segment</code> = <strong>Paket</strong> (jo&#39;natuvchi va qabul qiluvchi IP manzillari).</li><li>Data Link: <code>Frame Header + Packet + Frame Trailer</code> = <strong>Freym</strong> (MAC manzillar va CRC xatolik tekshiruvi).</li><li>Physical: Freym <code>0</code> va <code>1</code> bitlar oqimiga aylanib kabeldan uzatiladi.</li></ul></li><li><strong>Dekapsulyatsiya (Qabul qilishda)</strong>: Qabul qiluvchi kompyuter har bir qatlamda o&#39;z sarlavhasini tekshirib yechib oladi va sof ma&#39;lumotni ilovaga yetkazadi.</li></ul><hr>',12))]),i("div",u,[i("h2",q,[s(l,{name:"file-text"}),a[3]||(a[3]=r(" 2. Amaliy topshiriqlar va yechimlari (Mentor uchun) ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-amaliy-topshiriqlar-va-yechimlari-mentor-uchun","aria-label":'Permalink to "<Icon name="file-text" /> 2. Amaliy topshiriqlar va yechimlari (Mentor uchun)"'},"​",-1))]),a[5]||(a[5]=t(`<h3 id="_1-topshiriq-tizim-tarmoq-interfeyslarini-tahlil-qilish" tabindex="-1">1-topshiriq. Tizim tarmoq interfeyslarini tahlil qilish <a class="header-anchor" href="#_1-topshiriq-tizim-tarmoq-interfeyslarini-tahlil-qilish" aria-label="Permalink to &quot;1-topshiriq. Tizim tarmoq interfeyslarini tahlil qilish&quot;">​</a></h3><p>Linuxda <code>ip a</code> (yoki <code>ip addr show</code>) buyrug&#39;ini bering. Tizimingizdagi lokal qaytish (<code>lo</code> - loopback) interfeysi va asosiy tarmoq kartasi (masalan, <code>eth0</code> yoki <code>enp0s3</code>) nomlarini, ularning MAC va IP manzillarini aniqlang.</p><p><strong>Yechim:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ip</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> a</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Tahlil:</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 1: lo — loopback interfeysi (127.0.0.1)</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 2: eth0 (yoki enp3s0) — fizik/virtual tarmoq interfeysi</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">#    link/ether aa:bb:cc:dd:ee:ff — 2-qatlam MAC manzili</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">#    inet 192.168.1.50/24 — 3-qatlam IPv4 manzili</span></span></code></pre></div><h3 id="_2-topshiriq-tarmoq-shlyuzini-default-gateway-aniqlash" tabindex="-1">2-topshiriq. Tarmoq shlyuzini (Default Gateway) aniqlash <a class="header-anchor" href="#_2-topshiriq-tarmoq-shlyuzini-default-gateway-aniqlash" aria-label="Permalink to &quot;2-topshiriq. Tarmoq shlyuzini (Default Gateway) aniqlash&quot;">​</a></h3><p><code>ip route</code> (yoki <code>ip r</code>) buyrug&#39;i yordamida tashqi dunyoga (Internetga) chiquvchi asosiy yo&#39;naltiruvchi (router/gateway) IP manzilini toping.</p><p><strong>Yechim:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ip</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> route</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Masalan: default via 192.168.1.1 dev eth0 proto dhcp metric 100</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Demak, Default Gateway (Router) manzili: 192.168.1.1</span></span></code></pre></div><h3 id="_3-topshiriq-ochiq-portlar-va-transport-qatlamini-tekshirish" tabindex="-1">3-topshiriq. Ochiq portlar va transport qatlamini tekshirish <a class="header-anchor" href="#_3-topshiriq-ochiq-portlar-va-transport-qatlamini-tekshirish" aria-label="Permalink to &quot;3-topshiriq. Ochiq portlar va transport qatlamini tekshirish&quot;">​</a></h3><p><code>ss -tulpn</code> buyrug&#39;i orqali tizimda qaysi xizmatlar TCP yoki UDP orqali qaysi portlarni tinglayotganini (LISTEN) aniqlang.</p><p><strong>Yechim:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ss</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -tulpn</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Natijada Netid (tcp/udp), Local Address:Port (masalan, *:22 SSH uchun, *:80 Nginx uchun) va Process nomi aks etadi.</span></span></code></pre></div><h3 id="_4-topshiriq-qatlamlar-bo-yicha-ma-lumot-uzatish-tahlili" tabindex="-1">4-topshiriq. Qatlamlar bo&#39;yicha ma&#39;lumot uzatish tahlili <a class="header-anchor" href="#_4-topshiriq-qatlamlar-bo-yicha-ma-lumot-uzatish-tahlili" aria-label="Permalink to &quot;4-topshiriq. Qatlamlar bo&#39;yicha ma&#39;lumot uzatish tahlili&quot;">​</a></h3><p>O&#39;quvchiga quyidagi savol beriladi: Foydalanuvchi brauzerda <code>https://google.com</code> ga kirganda, OSI modelining 7, 4, 3 va 2-qatlamlarida qanday ma&#39;lumotlar qo&#39;shiladi?</p><p><strong>Yechim:</strong></p><ul><li>7-qatlam (Application): HTTP GET so&#39;rovi va TLS shifrlangan ma&#39;lumot.</li><li>4-qatlam (Transport): Manba va manzil portlari (masalan, manzil porti <code>443</code>).</li><li>3-qatlam (Network): Foydalanuvchi IP manzili va Google serveri IP manzili.</li><li>2-qatlam (Data Link): Kompyuterning tarmoq kartasi MAC manzili va Router (Default Gateway) MAC manzili.</li></ul><hr>`,17))]),i("div",y,[i("h2",g,[s(l,{name:"file-text"}),a[6]||(a[6]=r(" 3. Tezkor nazorat savollari (Dars yakuni) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-tezkor-nazorat-savollari-dars-yakuni","aria-label":'Permalink to "<Icon name="file-text" /> 3. Tezkor nazorat savollari (Dars yakuni)"'},"​",-1))]),a[8]||(a[8]=t("<ol><li><strong>OSI modeli nima uchun aynan 7 qatlamga bo&#39;lingan?</strong><em>Javob:</em> Tarmoq texnologiyalarini standartlashtirish, turli ishlab chiqaruvchilar qurilmalarining bir-biri bilan muammosiz ishlashini ta&#39;minlash va har bir qatlamni mustaqil yangilash imkonini berish uchun.</li><li><strong>Switch (kommutator) bilan Router (marshrutizator) OSI modelining qaysi qatlamlarida ishlaydi?</strong><em>Javob:</em> Switch 2-qatlamda (Data Link — MAC manzil bo&#39;yicha), Router esa 3-qatlamda (Network — IP manzil bo&#39;yicha) ishlaydi.</li><li><strong>Enkapsulyatsiya jarayonida ma&#39;lumotlar birligi (PDU) qanday nomlanadi?</strong><em>Javob:</em> 4-qatlamda — Segment, 3-qatlamda — Paket, 2-qatlamda — Freym, 1-qatlamda — Bitlar.</li><li><strong>TCP/IP modelida OSI ning qaysi qatlamlari yagona «Application» qatlamiga birlashtirilgan?</strong><em>Javob:</em> 7 (Application), 6 (Presentation) va 5 (Session) qatlamlari.</li></ol>",1))])])}const z=o(h,[["render",k]]);export{T as __pageData,z as default};
